1	import React, { useState, useCallback } from 'react';
2	
3	interface MagicWandButtonProps {
4	  noteId: string;
5	  onSendToLaunchpad?: (noteId: string) => Promise<void>;
6	  disabled?: boolean;
7	}
8	
9	function Sparkle({ delay, x, y }: { delay: number; x: number; y: number }) {
10	  return (
11	    <span
12	      className="absolute w-1 h-1 rounded-full bg-purple-300"
13	      style={{
14	        left: `${x}%`,
15	        top: `${y}%`,
16	        animation: `mw-sparkle 1.2s ease-in-out ${delay}s infinite`,
17	        opacity: 0,
18	      }}
19	    />
20	  );
21	}
22	
23	export function MagicWandButton({ noteId, onSendToLaunchpad, disabled }: MagicWandButtonProps) {
24	  const [isLoading, setIsLoading] = useState(false);
25	  const [showTooltip, setShowTooltip] = useState(false);
26	  const [isHovered, setIsHovered] = useState(false);
27	
28	  const handleClick = useCallback(async () => {
29	    if (!onSendToLaunchpad || isLoading) return;
30	    setIsLoading(true);
31	    try {
32	      await onSendToLaunchpad(noteId);
33	    } finally {
34	      setIsLoading(false);
35	    }
36	  }, [onSendToLaunchpad, noteId, isLoading]);
37	
38	  const sparkles = [
39	    { delay: 0, x: 15, y: 10 },
40	    { delay: 0.3, x: 80, y: 15 },
41	    { delay: 0.6, x: 70, y: 75 },
42	    { delay: 0.9, x: 20, y: 70 },
43	    { delay: 0.45, x: 50, y: 5 },
44	    { delay: 0.75, x: 85, y: 50 },
45	  ];
46	
47	  return (
48	    <div className="relative inline-block">
49	      {/* Tooltip */}
50	      {showTooltip && (
51	        <div
52	          className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap
53	            bg-purple-900/90 text-purple-100 border border-purple-400/30 shadow-lg shadow-purple-500/20
54	            animate-in fade-in slide-in-from-bottom-1 duration-200"
55	        >
56	          Send to Launchpad
57	          <div className="absolute top-full left-1/2 -translate-x-1/2 -mt-px">
58	            <div className="w-2 h-2 rotate-45 bg-purple-900/90 border-r border-b border-purple-400/30" />
59	          </div>
60	        </div>
61	      )}
62	
63	      <button
64	        onClick={handleClick}
65	        disabled={disabled || isLoading}
66	        aria-label="Send to Launchpad"
67	        aria-busy={isLoading}
68	        onMouseEnter={() => { setShowTooltip(true); setIsHovered(true); }}
69	        onMouseLeave={() => { setShowTooltip(false); setIsHovered(false); }}
70	        className={`
71	          relative flex items-center justify-center w-10 h-10 rounded-full
72	          bg-gradient-to-br from-purple-500/25 via-purple-600/20 to-fuchsia-700/25
73	          backdrop-blur-sm border border-purple-300/25
74	          transition-all duration-300 ease-out
75	          hover:from-purple-500/40 hover:via-purple-600/35 hover:to-fuchsia-700/40
76	          hover:border-purple-300/50 hover:shadow-lg hover:shadow-purple-500/25
77	          active:scale-90
78	          disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:shadow-none
79	          ${isLoading ? 'animate-pulse' : ''}
80	          ${isHovered && !isLoading ? 'ring-2 ring-purple-400/20 ring-offset-1 ring-offset-transparent' : ''}
81	        `}
82	      >
83	        {/* Sparkles */}
84	        {isHovered && !isLoading && sparkles.map((s, i) => (
85	          <Sparkle key={i} delay={s.delay} x={s.x} y={s.y} />
86	        ))}
87	
88	        {/* Wand icon */}
89	        <img
90	          src="/icons/magic-wand.png"
91	          alt=""
92	          aria-hidden="true"
93	          className={`w-6 h-6 object-contain transition-transform duration-300 ${isHovered ? 'scale-110' : ''}`}
94	        />
95	
96	        {/* Subtle inner glow on hover */}
97	        {isHovered && !isLoading && (
